mapper.sql:
WHERE lgns.deleted_at IS NULL
AND lgns.sido_name = #{sidoName}
AND lgns.validation_status_code = #{validationStatusCode}
AND lgns.collection_status_code = #{collectionStatusCode}
AND lgns.source_board_type_code = #{sourceBoardTypeCode}
AND lgns.collection_policy_code = #{collectionPolicyCode}
AND lgns.is_semantically_verified = #{semanticallyVerified}
AND ( CASE WHEN NOT lgns.is_semantically_verified OR lgns.source_board_type_code IN ('UNVERIFIED', 'PRESS_RELEASE') OR lgns.collection_policy_code = 'EXCLUDED' THEN 'SEMANTIC_MISMATCH' WHEN latest_result.result_status_code = 'PARTIAL_FAILED' OR lgns.last_error_code IN ( 'REQUIRED_FIELDS_MISSING', 'JSON_REQUIRED_FIELDS_MISSING', 'ITEM_FIELDS_MISSING', 'JSON_ITEM_FIELDS_MISSING' ) THEN 'PARTIAL_FIELDS' WHEN lgns.last_error_code IN ('PARSER_ERROR', 'PARSER_NOT_CONFIGURED', 'LIST_SELECTOR_NOT_MATCHED', 'HEURISTIC_ITEMS_NOT_FOUND', 'UNSUPPORTED_CONTENT_TYPE', 'JSON_PARSER_NOT_CONFIGURED', 'JSON_ITEMS_NOT_FOUND', 'JSON_PARSE_ERROR', 'DAEJEON_EMINWON_ITEMS_NOT_FOUND') THEN 'PARSER_FAILED' WHEN lgns.last_error_code = 'PROCESSING_FAILED' THEN 'PROCESSING_FAILED' WHEN lgns.last_error_code IN ( 'RETRYABLE', 'NETWORK_ERROR', 'DNS_LOOKUP_FAILED', 'TLS_HANDSHAKE_FAILED', 'CONNECTION_REFUSED', 'CONNECTION_RESET', 'HTTP_ERROR', 'EMPTY_RESPONSE', 'COLLECTION_INTERRUPTED', 'URL_VALIDATION_FAILED', 'REDIRECT_URL_BLOCKED', 'TOO_MANY_REDIRECTS', 'REDIRECT_LOCATION_MISSING', 'ACCESS_BLOCKED' ) THEN 'TRANSPORT_FAILED' WHEN lgns.last_error_code IS NOT NULL THEN 'UNCLASSIFIED_ERROR' WHEN coalesce(latest_result.excluded_count, 0) > 0 THEN 'IRRELEVANT_CONTENT' ELSE NULL END ) = #{diagnosticReasonCode}
AND lgns.is_enabled = #{enabled}
AND ( lgns.public_code ILIKE concat('%', #{keyword}, '%') OR lgns.sido_name ILIKE concat('%', #{keyword}, '%') OR lgns.sigungu_name ILIKE concat('%', #{keyword}, '%') OR lgns.institution_name ILIKE concat('%', #{keyword}, '%') OR lgns.notice_url ILIKE concat('%', #{keyword}, '%') )

mapper.select:
-- Select verified and enabled local-government notice sources for collection. SELECT FROM local_government_notice_sources lgns INNER JOIN local_government_notice_parser_profiles lgnpp ON lgnpp.profile_code = lgns.parser_profile_code AND lgnpp.is_enabled = true AND lgnpp.parser_type_code <> 'MANUAL_ONLY' LEFT JOIN LATERAL ( SELECT result.result_status_code, result.discovered_count, result.failed_count, result.excluded_count, result.finished_at FROM announcement_source_collection_source_results result WHERE result.local_government_source_id = lgns.id ORDER BY result.started_at DESC, result.id DESC LIMIT 1 ) latest_result ON true WHERE lgns.deleted_at IS NULL AND lgns.is_enabled = true AND lgns.validation_status_code = 'VERIFIED' AND lgns.is_semantically_verified = true AND lgns.source_board_type_code <> 'UNVERIFIED' AND lgns.collection_policy_code <> 'EXCLUDED'
AND lgns.id = #{sourceId}
ORDER BY lgns.last_collected_at ASC NULLS FIRST, lgns.sido_name ASC, lgns.sigungu_name ASC LIMIT #{maxCount}

mapper.insert:
-- Insert a local-government collection schedule awaiting approval.
INSERT INTO announcement_source_collection_schedules (
    id, provider_code, schedule_name, cron_expression, timezone, max_count, requested_by, next_run_at
) VALUES (
    #{scheduleId}, #{providerCode}, #{scheduleName}, #{cronExpression}, #{timezone}, #{maxCount},
    #{requestedBy}, #{nextRunAt}
)

-- Claim an approved schedule slot exactly once.
INSERT INTO announcement_source_schedule_executions (
    id, schedule_id, scheduled_for, request_id, run_id, execution_status_code, error_message
) VALUES (
    #{executionId}, #{scheduleId}, #{scheduledFor}, #{requestId}, #{runId}, #{executionStatusCode}, #{errorMessage}
)
ON CONFLICT (schedule_id, scheduled_for) DO NOTHING
